    const task: Task = {
      id: database.nextId++, title, status: "open", tags: normalizeTags(flags.get("--tags")),
      createdAt: new Date().toISOString(), ...(due === undefined ? {} : { due }),
    };
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
